{
  "passageId": "gongsun-long-later-mohists",
  "items": [
    {
      "id": "R1",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "명실 문제의 논의가 정치·윤리적 차원에서 독립적인 철학 영역으로 옮겨 가므로 시대적·논의적 전개에 해당한다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "미분화된 물에서 각각의 개체인 실이 분화되는 흐름으로, 원인 작용보다는 분화 과정의 앞뒤 상태를 연결한다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "실을 지시한다는 명의 기능을 실들 사이의 차이를 구별하고 확정하는 기능으로 더 자세히 설명한다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "서로 다른 실이 구별되지 않는 것이 사람마다 같은 명으로 다른 실을 지시하는 혼란을 실제로 일으킨다는 관계이다."
    },
    {
      "id": "R5",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "동일한 명으로 서로 다른 실을 지시할 때 생기는 혼란이 일대일 대응을 지켜야 한다는 당위적 주장의 근거로 제시된다."
    },
    {
      "id": "R6",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "엄격한 일대일 대응은 명의 역할 수행에서 오해와 문제를 막으려는 목적을 위한 수단이다."
    },
    {
      "id": "R7",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "같은 이론 안에서 두 단어가 부르는 대상이 각각 형체와 색이라는 차이를 비교한다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "흰 말에는 희다는 속성이 함께한다는 사실을 근거로 흰 말과 말이 다르다는 판단을 도출한다."
    },
    {
      "id": "R9",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "말과 흰 말을 각각 구하는 경우를 데려올 수 있는 대상이라는 동일한 기준에서 비교하여 차이를 드러낸다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "형체와 색 속성의 차이에 대한 설명이 흰 말은 말이 아니라는 주장을 뒷받침하는 논거이다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "말과 흰 말을 구할 때 충족 가능한 대상이 다르다는 사실로 백마비마 주장을 뒷받침한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 명이 지시하는 실이 다르다는 판단이 두 명의 용법을 구분해야 한다는 당위적 결론의 근거이다."
    },
    {
      "id": "R13",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "공손룡은 일상에서 말로 흰 말을 지시하는 통상적 용법을 문제 삼으며 두 명의 용법을 구분해야 한다고 주장한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "명실의 일대일 대응이라는 일반 원칙을 말과 흰 말의 용법이라는 구체적인 사례에 가져다 적용한다."
    },
    {
      "id": "R15",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 흰 말도 말이라고 명시적으로 주장하여 공손룡의 백마비마 주장을 반박한다."
    },
    {
      "id": "R16",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 하나의 실을 여러 명으로 지시할 수 있다고 하여 공손룡의 일실일명 원칙을 부정한다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "흰 말이 흰 말과 말이라는 두 명으로 지시되는 경우는 하나의 실에 여러 명이 대응한다는 설명의 구체적 사례이다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "검은 말이 검은 말과 말이라는 두 명으로 지시되는 경우는 하나의 실에 여러 명이 대응한다는 설명의 구체적 사례이다."
    },
    {
      "id": "R19",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 하나의 명이 여러 사물을 지시할 수 있다고 하여 공손룡의 일명일실 원칙에 반대한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "서로 다른 두 새를 모두 학이라고 부르는 경우로 하나의 명이 여러 실을 지시한다는 주장을 예시한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "지시 대상의 범위와 상황에 따라 명을 구분하는 논의가 엄격한 명실 일대일 대응을 부정하는 입장을 뒷받침한다."
    },
    {
      "id": "R22",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "달명의 지시 대상인 천지 만물을 공손룡의 물이라는 개념과 대응시켜 그 뜻을 풀어 설명한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "말이라는 명은 공통 속성을 공유하는 사물들을 지시하는 유명의 구체적 예이다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "새라는 유명을 특정한 한 마리에 사용하는 경우가 유명을 한 개체에 대응시켜 만든 사명을 예시한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유명을 단 하나의 개체에 대응시키면 사명이 된다는 정의에서 새의 명 유형이 지시 대상 수에 따라 정해진다는 판단이 도출된다."
    },
    {
      "id": "R26",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "후기 묵가는 복수 대응을 인정하는 입장으로 공손룡의 엄격한 일대일 대응론을 명시적으로 반박한다."
    }
  ]
}

